INSERT INTO receita (id_receita, modo_preparo, tempo_preparo, rendimento_qtd, rendimento_un, complexidade, data_criacao) VALUES
  (1, 'Massa branca: Bater ovos e acucar, juntar leite e oleo, incorporar farinha e fermento. Assar 40 min a 180C.', 50, 1, 'bolo 25cm', 'baixa', '2025-09-25 00:00:00'),
  (2, 'Massa de chocolate: Misturar secos com cacau, juntar ovos, leite e oleo. Assar 40 min a 180C.', 50, 1, 'bolo 25cm', 'baixa', '2025-09-25 00:00:00'),
  (3, 'Massa de cenoura: Bater cenoura, ovos e oleo no liquidificador; misturar farinha, acucar e fermento. Assar 40 min.', 50, 1, 'bolo 25cm', 'baixa', '2025-09-25 00:00:00'),
  (4, 'Massa de maca com canela: Picar as macas, bater manteiga e acucar, juntar ovos, farinha e macas. Assar 45 min.', 60, 1, 'bolo 25cm', 'media', '2025-09-25 00:00:00'),
  (5, 'Brigadeiro: Cozinhar leite condensado, manteiga e chocolate ate desgrudar. Enrolar e passar no granulado.', 60, 50, 'unidades', 'baixa', '2025-09-25 00:00:00'),
  (6, 'Beijinho: Cozinhar leite condensado com manteiga e coco. Enrolar e passar no coco.', 60, 50, 'unidades', 'baixa', '2025-09-25 00:00:00'),
  (7, 'Ganache de chocolate: Derreter chocolate meio amargo com creme de leite.', 15, 1, 'cobertura de bolo', 'baixa', '2025-09-25 00:00:00'),
  (8, 'Recheio de brigadeiro de colher: Cozinhar leite condensado, creme de leite, cacau e manteiga ate ponto cremoso.', 25, 1, 'recheio de bolo', 'baixa', '2025-09-25 00:00:00'),
  (9, 'Torta de limao: Massa amanteigada assada, creme de limao com leite condensado e merengue macaroc.', 90, 1, 'torta 22cm', 'media', '2025-09-25 00:00:00'),
  (10, 'Torta holandesa: Base crocante, creme de manteiga com creme de leite, cobertura de chocolate ao leite.', 90, 1, 'torta 22cm', 'media', '2025-09-25 00:00:00'),
  (11, 'Torta de morango: Massa amanteigada, creme de confeiteiro e morangos frescos.', 100, 1, 'torta 22cm', 'media', '2025-09-25 00:00:00'),
  (12, 'Brownie: Derreter chocolate com manteiga, juntar acucar, ovos, cacau e farinha. Assar 25 min.', 45, 16, 'pedacos', 'baixa', '2025-09-25 00:00:00'),
  (13, 'Cupcake de chocolate: Massa de cupcake em forminhas, cobertura de ganache de chocolate ao leite.', 60, 12, 'unidades', 'media', '2025-09-25 00:00:00'),
  (14, 'Trufa: Ganache de chocolate meio amargo, casquinha de chocolate ao leite.', 90, 30, 'unidades', 'alta', '2025-09-25 00:00:00'),
  (15, 'Bombom de morango: Morango envolto em brigadeiro branco e banhado em chocolate ao leite.', 90, 20, 'unidades', 'alta', '2025-09-25 00:00:00'),
  (16, 'Pave de chocolate no copo: Camadas de creme de chocolate e mousse montadas em copos.', 60, 10, 'copos', 'baixa', '2025-09-25 00:00:00'),
  (17, 'Ovo de Pascoa trufado: Casca de chocolate ao leite recheada com trufa de meio amargo.', 120, 1, 'ovo 350g', 'alta', '2025-09-25 00:00:00');
