-- ---------- Ajusta as sequencias (os IDs acima foram fixados) ----------
SELECT setval(pg_get_serial_sequence('usuario', 'id_usuario'), (SELECT max(id_usuario) FROM usuario));
SELECT setval(pg_get_serial_sequence('endereco', 'id_endereco'), (SELECT max(id_endereco) FROM endereco));
SELECT setval(pg_get_serial_sequence('fornecedor', 'id_fornecedor'), (SELECT max(id_fornecedor) FROM fornecedor));
SELECT setval(pg_get_serial_sequence('insumo', 'id_insumo'), (SELECT max(id_insumo) FROM insumo));
SELECT setval(pg_get_serial_sequence('receita', 'id_receita'), (SELECT max(id_receita) FROM receita));
SELECT setval(pg_get_serial_sequence('item_receita', 'id_item_receita'), (SELECT max(id_item_receita) FROM item_receita));
SELECT setval(pg_get_serial_sequence('produto', 'id_produto'), (SELECT max(id_produto) FROM produto));
SELECT setval(pg_get_serial_sequence('opcao_personalizacao', 'id_opcao'), (SELECT max(id_opcao) FROM opcao_personalizacao));
SELECT setval(pg_get_serial_sequence('pedido', 'id_pedido'), (SELECT max(id_pedido) FROM pedido));
SELECT setval(pg_get_serial_sequence('item_pedido', 'id_item_pedido'), (SELECT max(id_item_pedido) FROM item_pedido));
SELECT setval(pg_get_serial_sequence('compra_insumo', 'id_compra_insumo'), (SELECT max(id_compra_insumo) FROM compra_insumo));
SELECT setval(pg_get_serial_sequence('item_compra_insumo', 'id_item_compra'), (SELECT max(id_item_compra) FROM item_compra_insumo));
SELECT setval(pg_get_serial_sequence('movimentacao_estoque', 'id_movimentacao_estoque'), (SELECT max(id_movimentacao_estoque) FROM movimentacao_estoque));

-- ---------- Traz as datas para "hoje" ----------
-- Os dados foram gerados com hoje = 2026-10-10. Aqui tudo e deslocado para perto da data atual,
-- em semanas inteiras (sabado continua sabado e domingo continua fechado), para que as
-- encomendas futuras continuem no futuro.
CREATE TEMP TABLE deslocamento AS
  SELECT (round((current_date - DATE '2026-10-10') / 7.0) * 7)::int AS dias;

UPDATE usuario     SET data_cadastro = data_cadastro + (SELECT dias FROM deslocamento) * interval '1 day',
                       data_nascimento = data_nascimento + (SELECT dias FROM deslocamento);
UPDATE funcionario SET data_contratacao = data_contratacao + (SELECT dias FROM deslocamento);
UPDATE receita     SET data_criacao = data_criacao + (SELECT dias FROM deslocamento) * interval '1 day';
UPDATE insumo      SET data_atualizacao = data_atualizacao + (SELECT dias FROM deslocamento) * interval '1 day';
UPDATE pedido      SET data_criacao = data_criacao + (SELECT dias FROM deslocamento) * interval '1 day',
                       data_entrega_ou_retirada = data_entrega_ou_retirada + (SELECT dias FROM deslocamento) * interval '1 day';
UPDATE compra_insumo SET data_compra = data_compra + (SELECT dias FROM deslocamento) * interval '1 day',
                         data_entrega = data_entrega + (SELECT dias FROM deslocamento) * interval '1 day';
UPDATE movimentacao_estoque SET data = data + (SELECT dias FROM deslocamento) * interval '1 day';

DROP TABLE deslocamento;
